/**
 * generated by stackra gen from services/commerce/stackra.manifest.json and the acme-platform
 * manifests of billing, content, experience and marketing at the revisions stackra.lock.yaml pins,
 * filtered to the `public` area — do not edit
 * Purpose: typed descriptors for every consumed public query, action and refusal: what loaders,
 *          submits, blocks (`accepts`) and sitemap sources name, and the shapes the site reads
 *          (`X$` the schema, `X` its type). Consumed services are inferred from the imports of
 *          this file.
 * Boundary: descriptors and shapes only; `gen/clients.server.ts` performs the call. A descriptor of
 *           another area never appears here: gen fails when a public-area member references one.
 *           Commerce keys carry their major (`@1`) and its refusal texts are the derived keys
 *           (`catalogue::errors.<code>.message`); the pinned acme-platform descriptors are copied
 *           as their revision publishes them. The storefront projection of a product is the public
 *           area's view of the catalogue, richer than the console's.
 * Runtime: isomorphic
 */
import { COLOR_TOKENS } from "@acme/brand";
import { actionRef, queryRef, refusalRef } from "@stackra/clients";
import { ContentEntryType } from "@stackra/content";
import { HttpMethod } from "@stackra/contracts";
import { Locale } from "@stackra/i18n";
import { Risk } from "@stackra/iam";
import { Enum } from "@stackra/validation";
import { currencyCode, publicId } from "@stackra/validation/runtime";
import { z } from "zod";
import { I18n } from "#stackra/i18n";

/**
 * The newest date listed in the producer's VersioningConfig at gen time; identical in every app of
 * the workspace.
 */
export const apiVersion = "2027-03-01" as const;

/** `catalogue.StorefrontImage$`: a media URL the image-variant helper can resize. */
const StorefrontImage$ = z.object({ url: z.string(), alt: z.string().nullable() });

/** `catalogue.StorefrontSeo$`: the merchant's page title and meta description overrides. */
const StorefrontSeo$ = z.object({
  title: z.string().nullable(),
  description: z.string().nullable(),
  noindex: z.boolean(),
});

/** `catalogue.StorefrontCollection$`: a collection the product is listed in. */
const StorefrontCollection$ = z.object({ title: z.string(), slug: z.string() });

/** `catalogue.StorefrontVariant$`: one variant with its price in the market currency. */
const StorefrontVariant$ = z.object({
  id: publicId("var"),
  sku: z.string(),
  priceMinor: z.number().int(),
  inStock: z.boolean(),
  options: z.record(z.string(), z.string()),
});

/** `catalogue.StorefrontProductCard$`: one product in a grid. */
export const StorefrontProductCard$ = z.object({
  id: publicId("prd"),
  title: z.string(),
  slug: z.string(),
  priceMinor: z.number().int(),
  currency: currencyCode(),
  image: StorefrontImage$.nullable(),
  inStock: z.boolean(),
});

/** One product card as the grid renders it. */
export type StorefrontProductCard = z.output<typeof StorefrontProductCard$>;

/** `catalogue.StorefrontProductView$`: one product's page. */
export const StorefrontProductView$ = z.object({
  id: publicId("prd"),
  title: z.string(),
  slug: z.string(),
  currency: currencyCode(),
  inStock: z.boolean(),
  images: z.array(StorefrontImage$),
  description: z.json().nullable(),
  variants: z.array(StorefrontVariant$),
  seo: StorefrontSeo$,
  collections: z.array(StorefrontCollection$),
});

/** One product as its page renders it. */
export type StorefrontProductView = z.output<typeof StorefrontProductView$>;

/** `catalogue.StorefrontProductPage$`: a cursor page of cards. */
const StorefrontProductPage$ = z.object({
  items: z.array(StorefrontProductCard$),
  nextCursor: z.string().exactOptional(),
  hasMore: z.boolean(),
});

/**
 * `catalogue.ListStorefrontProductsInput$`: cursor, limit, an optional phrase and collection slug.
 */
const ListStorefrontProductsInput$ = z.object({
  cursor: z.string().exactOptional(),
  limit: z.number().int().min(1).max(100).default(20),
  search: z.string().max(200).exactOptional(),
  collection: z.string().max(200).exactOptional(),
});

/** `catalogue.SearchProductsInput$`: the phrase, an optional collection slug, cursor and limit. */
const SearchProductsInput$ = z.object({
  q: z.string().min(2).max(64),
  collection: z.string().max(200).exactOptional(),
  cursor: z.string().exactOptional(),
  limit: z.number().int().min(1).max(100).default(20),
});

/** `content.Entry$`: one content entry; fields are the content type's plain strings. */
const Entry$ = z.object({ id: z.string(), fields: z.record(z.string(), z.string()) });

/** `billing.Plan$`: one rung of a plan ladder, priced in the request's market. */
const Plan$ = z.object({
  key: z.string(),
  name: z.string(),
  prices: z.object({ month: z.number().int().nullable(), year: z.number().int().nullable() }),
  currency: currencyCode(),
  limits: z.array(z.string()),
  entitlements: z.array(z.string()),
  highlighted: z.boolean(),
});

/**
 * `sites.Site$`: the tenant site a host resolves to; `brand` overrides any subset of the brand
 * tokens.
 */
const Site$ = z.object({
  id: z.string(),
  name: z.string(),
  market: z.object({ key: z.string(), currency: currencyCode() }),
  indexable: z.boolean(),
  brand: z.partialRecord(
    z.enum(Object.keys(COLOR_TOKENS) as [keyof typeof COLOR_TOKENS]),
    z.string(),
  ),
});

/** `experience.PublishedDocument$`: a tenant's published L2 document and its SEO fields. */
const PublishedDocument$ = z.object({
  key: z.string(),
  version: z.number().int(),
  root: z.unknown(),
  seo: z.object({
    title: z.string(),
    description: z.string().nullable(),
    noindex: z.boolean(),
    image: z.string().nullable(),
  }),
});

/** Commerce, public area. */
export const Commerce = {
  queries: {
    ListStorefrontProducts: queryRef("catalogue.product.list_storefront@1", {
      input: ListStorefrontProductsInput$,
      output: StorefrontProductPage$,
      http: { method: HttpMethod.Get, path: "/public/products" },
    }),
    SearchProducts: queryRef("catalogue.product.search@1", {
      input: SearchProductsInput$,
      output: StorefrontProductPage$,
      http: { method: HttpMethod.Get, path: "/public/products/search" },
    }),
    GetProductBySlug: queryRef("catalogue.product.get_by_slug@1", {
      input: z.object({ slug: z.string().max(200) }),
      output: StorefrontProductView$,
      http: { method: HttpMethod.Get, path: "/public/products/by-slug/:slug" },
    }),
  },
  refusals: {
    product_not_found: refusalRef("catalogue.product_not_found", {
      message: I18n.catalogue.errors.product_not_found.message,
    }),
  },
} as const;

/** Billing, public area. */
export const Billing = {
  queries: {
    ListPlans: queryRef("billing.catalog.plan.list", {
      input: z.object({ product: z.string() }),
      output: z.object({ trialDays: z.number().int(), plans: z.array(Plan$) }),
      http: { method: HttpMethod.Get, path: "/public/plans" },
    }),
  },
} as const;

/** Content, public area. */
export const Content = {
  queries: {
    ListEntries: queryRef("content.entry.list", {
      input: z.object({
        siteId: z.string(),
        type: z.enum(Enum.values(ContentEntryType)),
        limit: z.number().int().exactOptional(),
      }),
      output: z.object({ entries: z.array(Entry$) }),
      http: { method: HttpMethod.Get, path: "/public/entries" },
    }),
  },
} as const;

/** Experience, public area: sites, documents, SEO. */
export const Experience = {
  queries: {
    ResolveSite: queryRef("sites.site.resolve", {
      input: z.object({ host: z.string() }),
      output: Site$.nullable(),
      http: { method: HttpMethod.Get, path: "/public/sites/resolve" },
    }),
    GetSite: queryRef("sites.site.get", {
      input: z.object({ siteId: z.string() }),
      output: Site$.nullable(),
      http: { method: HttpMethod.Get, path: "/public/sites/:siteId" },
    }),
    GetDocument: queryRef("experience.document.get", {
      input: z.union([z.object({ key: z.string() }), z.object({ path: z.string() })]),
      output: PublishedDocument$.nullable(),
      http: { method: HttpMethod.Get, path: "/public/experience/documents" },
    }),
    GetPagesSitemap: queryRef("pages.sitemap.get", {
      input: z.object({ siteId: z.string() }),
      output: z.object({
        entries: z.array(z.object({ path: z.string(), updatedAt: z.string().exactOptional() })),
      }),
      http: { method: HttpMethod.Get, path: "/public/pages/sitemap" },
    }),
    ResolveRedirect: queryRef("seo.redirect.resolve", {
      input: z.object({ host: z.string(), path: z.string() }),
      output: z
        .object({ to: z.string(), status: z.union([z.literal(301), z.literal(302)]) })
        .nullable(),
      http: { method: HttpMethod.Get, path: "/public/seo/redirects/resolve" },
    }),
  },
  actions: {
    RecordNotFound: actionRef("seo.not_found.record", {
      input: z.object({
        host: z.string(),
        path: z.string(),
        referrer: z.string().exactOptional(),
      }),
      output: z.object({}),
      http: { method: HttpMethod.Post, path: "/public/seo/not-found" },
      risk: Risk.L0,
    }),
  },
  refusals: {
    not_found: refusalRef("experience.not_found", { message: I18n.experience.refusals.not_found }),
  },
} as const;

/** Marketing, public area. */
export const Marketing = {
  actions: {
    CreateLead: actionRef("leads.lead.create", {
      input: z.object({
        name: z.string(),
        email: z.string(),
        company: z.string().exactOptional(),
        message: z.string(),
        consent: z.literal(true),
        locale: z.enum(Enum.values(Locale)),
        captchaToken: z.string(),
      }),
      output: z.object({ leadId: z.string() }),
      http: { method: HttpMethod.Post, path: "/public/leads" },
      risk: Risk.L0,
    }),
  },
  refusals: {
    rate_limited: refusalRef("leads.rate_limited", { message: I18n.leads.refusals.rate_limited }),
    captcha_failed: refusalRef("leads.captcha_failed", {
      message: I18n.leads.refusals.captcha_failed,
    }),
  },
} as const;
